"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  AuthHeader,
  AuthDivider,
  AuthSocial,
  AuthFooter,
  type AuthProvider,
} from "@/components/ui/e-auth";

interface RegisterBlockProps {
  layout?: "card" | "split" | "centered";
  logo?: React.ReactNode;
  social?: AuthProvider[];
  socialStyle?: "buttons" | "icons";
  socialPosition?: "top" | "bottom";
  image?: React.ReactNode;
  showTerms?: boolean;
  showName?: boolean;
  showConfirmPassword?: boolean;
  onRegister?: (data: { name?: string; email: string; password: string; confirmPassword?: string }) => void;
  onSocialLogin?: (provider: AuthProvider) => void;
  onLogin?: () => void;
  loginHref?: string;
  className?: string;
}

function RegisterForm({
  logo,
  social = [],
  socialStyle = "buttons",
  socialPosition = "bottom",
  showTerms,
  showName = true,
  showConfirmPassword = false,
  onRegister,
  onSocialLogin,
  onLogin,
  loginHref,
  centered,
}: Omit<RegisterBlockProps, "layout" | "image" | "className"> & { centered?: boolean }) {
  const [name, setName] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [password, setPassword] = React.useState("");
  const [confirmPassword, setConfirmPassword] = React.useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onRegister?.({
      name: showName ? name : undefined,
      email,
      password,
      confirmPassword: showConfirmPassword ? confirmPassword : undefined,
    });
  };

  return (
    <div className="flex flex-col gap-6">
      <AuthHeader
        logo={logo}
        heading="Create your account"
        description="Enter your details to get started"
        centered={centered}
      />

      {social.length > 0 && socialPosition === "top" && (
        <>
          <AuthSocial providers={social} style={socialStyle} onProvider={onSocialLogin} />
          <AuthDivider />
        </>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        {showName && (
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="register-name">Name</Label>
            <Input
              id="register-name"
              type="text"
              placeholder="John Doe"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
        )}

        <div className="flex flex-col gap-1.5">
          <Label htmlFor="register-email">Email</Label>
          <Input
            id="register-email"
            type="email"
            placeholder="m@example.com"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-1.5">
          <Label htmlFor="register-password">Password</Label>
          <Input
            id="register-password"
            type="password"
            required
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
        </div>

        {showConfirmPassword && (
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="register-confirm">Confirm Password</Label>
            <Input
              id="register-confirm"
              type="password"
              required
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
            />
          </div>
        )}

        <Button type="submit" className="w-full">
          Create account
        </Button>
      </form>

      {social.length > 0 && socialPosition === "bottom" && (
        <>
          <AuthDivider />
          <AuthSocial providers={social} style={socialStyle} onProvider={onSocialLogin} />
        </>
      )}

      <AuthFooter
        mode="register"
        onSwitch={onLogin}
        switchHref={loginHref}
        showTerms={showTerms}
      />
    </div>
  );
}

function RegisterBlock({
  layout = "card",
  logo,
  social = ["google"],
  socialStyle = "buttons",
  socialPosition = "bottom",
  image,
  showTerms,
  showName = true,
  showConfirmPassword = false,
  onRegister,
  onSocialLogin,
  onLogin,
  loginHref,
  className,
}: RegisterBlockProps) {
  const formProps = {
    logo,
    social,
    socialStyle,
    socialPosition,
    showTerms,
    showName,
    showConfirmPassword,
    onRegister,
    onSocialLogin,
    onLogin,
    loginHref,
  };

  if (layout === "split") {
    return (
      <div
        data-slot="register-block"
        data-layout="split"
        className={cn("grid min-h-svh lg:grid-cols-2", className)}
      >
        <div className="flex flex-col gap-6 p-8 lg:p-10">
          {logo && <div>{logo}</div>}
          <div className="flex flex-1 items-center justify-center">
            <div className="w-full max-w-sm">
              <RegisterForm {...formProps} logo={undefined} />
            </div>
          </div>
        </div>
        <div className="bg-muted relative hidden lg:block">
          {image && <div className="absolute inset-0 overflow-hidden">{image}</div>}
        </div>
      </div>
    );
  }

  if (layout === "centered") {
    return (
      <div
        data-slot="register-block"
        data-layout="centered"
        className={cn("bg-background flex min-h-svh flex-col items-center justify-center p-8", className)}
      >
        <div className="w-full max-w-sm">
          <RegisterForm {...formProps} centered />
        </div>
      </div>
    );
  }

  return (
    <div
      data-slot="register-block"
      data-layout="card"
      className={cn("bg-background flex min-h-svh items-center justify-center p-6 md:p-10", className)}
    >
      <div className="w-full max-w-sm">
        <div className="rounded-xl border bg-card p-8 shadow-sm">
          <RegisterForm {...formProps} />
        </div>
      </div>
    </div>
  );
}

export { RegisterBlock };
export type { RegisterBlockProps };
